    useModalWithSubject,
    useConfirmationModal,
    Action: Dialog.Action,
    ActionIcon: Dialog.ActionIcon,
    CancelAction: Dialog.CancelAction,
    SubmitAction: Dialog.SubmitAction,
  },
);

