export type LayoutDecoratorProps = ComponentProps<'div'> & {
  size?: undefined | 'x-small' | 'small' | 'medium' | 'large' | 'x-large',
  resize?: undefined | 'none' | 'inline' | 'block' | 'both',
};
export const LayoutDecorator = (props: LayoutDecoratorProps) => {
  const {
